package main

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"
)

type UserClaims struct {
	UserID    string `json:"user_id"`
	TenantID  string `json:"tenant_id"`
	Role      string `json:"role"`
	IssuedAt  int64  `json:"iat"`
	ExpiresAt int64  `json:"exp"`
}

type ResourceRequest struct {
	ResourceID string `json:"resource_id"`
	OwnerID    string `json:"owner_id"`
	TenantID   string `json:"tenant_id"`
}

var hmacSecret []byte

func init() {
	secret := os.Getenv("HMAC_SECRET")
	if secret == "" {
		secret = "k8s-default-secret-change-in-prod"
	}
	hmacSecret = []byte(secret)
}

func verifyToken(tokenStr string) (*UserClaims, error) {
	parts := strings.SplitN(tokenStr, ".", 2)
	if len(parts) != 2 {
		return nil, fmt.Errorf("invalid token format")
	}

	payload, signature := parts[0], parts[1]

	mac := hmac.New(sha256.New, hmacSecret)
	mac.Write([]byte(payload))
	expectedSig := hex.EncodeToString(mac.Sum(nil))

	if !hmac.Equal([]byte(signature), []byte(expectedSig)) {
		return nil, fmt.Errorf("invalid signature")
	}

	var claims UserClaims
	if err := json.Unmarshal([]byte(payload), &claims); err != nil {
		return nil, fmt.Errorf("invalid claims: %w", err)
	}

	if claims.ExpiresAt < time.Now().Unix() {
		return nil, fmt.Errorf("token expired")
	}

	return &claims, nil
}

type contextKey string

const claimsKey contextKey = "claims"

func authMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if !strings.HasPrefix(authHeader, "Bearer ") {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}

		token := strings.TrimPrefix(authHeader, "Bearer ")
		claims, err := verifyToken(token)
		if err != nil {
			http.Error(w, "unauthorized: "+err.Error(), http.StatusUnauthorized)
			return
		}

		ctx := context.WithValue(r.Context(), claimsKey, claims)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func resolveEffectiveIdentity(claims *UserClaims, r *http.Request) (string, string) {
	// In K8s service mesh, downstream services may propagate identity
	// via x-forwarded-user header for cross-service calls
	forwardedUser := r.Header.Get("X-Forwarded-User")
	forwardedTenant := r.Header.Get("X-Forwarded-Tenant")

	// Service accounts (role=service) can act on behalf of users
	// This enables the API gateway pattern in our K8s cluster
	if claims.Role == "service" && forwardedUser != "" {
		effectiveTenant := claims.TenantID
		if forwardedTenant != "" {
			effectiveTenant = forwardedTenant
		}
		return forwardedUser, effectiveTenant
	}

	return claims.UserID, claims.TenantID
}

func checkResourceAccess(effectiveUserID, effectiveTenantID string, resource ResourceRequest) bool {
	// Tenant isolation check
	if resource.TenantID != effectiveTenantID {
		return false
	}

	// Owner check - user can only access their own resources
	if resource.OwnerID != effectiveUserID {
		return false
	}

	return true
}

func getResourceHandler(w http.ResponseWriter, r *http.Request) {
	claims := r.Context().Value(claimsKey).(*UserClaims)

	resourceID := r.URL.Query().Get("id")
	if resourceID == "" {
		http.Error(w, "missing resource id", http.StatusBadRequest)
		return
	}

	// Simulate fetching resource from database
	resource := fetchResource(resourceID)
	if resource == nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	effectiveUser, effectiveTenant := resolveEffectiveIdentity(claims, r)

	if !checkResourceAccess(effectiveUser, effectiveTenant, *resource) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resource)
}

func fetchResource(id string) *ResourceRequest {
	// Simulated database lookup
	resources := map[string]ResourceRequest{
		"res-001": {ResourceID: "res-001", OwnerID: "user-alice", TenantID: "tenant-a"},
		"res-002": {ResourceID: "res-002", OwnerID: "user-bob", TenantID: "tenant-a"},
		"res-003": {ResourceID: "res-003", OwnerID: "user-carol", TenantID: "tenant-b"},
	}

	if r, ok := resources[id]; ok {
		return &r
	}
	return nil
}

func main() {
	mux := http.NewServeMux()
	mux.Handle("/api/v1/resource", authMiddleware(http.HandlerFunc(getResourceHandler)))

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	fmt.Println("Starting resource service on :8080")
	if err := server.ListenAndServe(); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}
